from pathlib import Path
import json,csv
R=Path(__file__).resolve().parents[1];O=R/'results/assistant_review'
data=(O/'review_queue.json').read_text(encoding='utf-8').replace('<','\\u003c')
page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>ELEC-VQA · 未决评分审理</title>
<style>
:root{--ink:#172c32;--teal:#087f75;--line:#d9e3e1}*{box-sizing:border-box}body{margin:0;background:#f4f7f5;color:var(--ink);font:15px/1.65 system-ui,"Microsoft YaHei",sans-serif}header{background:#153a3d;color:white;padding:25px max(24px,calc((100vw - 1440px)/2))}h1{margin:0;font-size:25px}header p{margin:8px 0;color:#c8dcd7}.wrap{max-width:1440px;margin:auto;padding:22px}.bar{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-bottom:16px}button,select,input,textarea{font:inherit;border:1px solid #bdcfca;background:white;border-radius:8px;padding:9px 12px;color:var(--ink)}button{cursor:pointer}button:hover{background:#e3efea}button.primary{background:var(--teal);color:white;border-color:var(--teal)}input{min-width:220px;flex:1}#status{font-weight:600;color:var(--teal)}.grid{display:grid;grid-template-columns:minmax(320px,.95fr) minmax(450px,1.15fr);gap:20px}.box{background:white;border:1px solid var(--line);border-radius:14px;padding:20px;margin-bottom:16px}.image{position:sticky;top:16px;align-self:start}.image img{width:100%;max-height:74vh;object-fit:contain;background:white;cursor:zoom-in}.pill{display:inline-block;padding:3px 9px;border-radius:5px;background:#e2efeb;font-size:12px;margin:0 5px 7px 0}h2{font-size:18px;margin:4px 0 10px}h3{font-size:14px;color:#44716a;margin:14px 0 5px}.text{white-space:pre-wrap;overflow-wrap:anywhere}.response{max-height:420px;overflow:auto;font-family:ui-monospace,monospace;font-size:13px;background:#f5f7f7;padding:15px;border-radius:8px}.score{font-size:28px;font-weight:700;color:var(--teal)}.note{color:#76531a;background:#fff6df;padding:12px;border-radius:8px;font-size:13px}.muted{font-size:12px;color:#687a78}.review{border:2px solid #82b7a6}textarea{width:100%;height:85px}details{margin-top:10px}summary{cursor:pointer;color:#476f68}a{color:var(--teal)}.pager{justify-content:space-between}#empty{text-align:center;padding:60px;background:white}dialog{max-width:96vw;max-height:96vh;padding:10px;border:0;border-radius:10px}dialog img{max-width:92vw;max-height:86vh}dialog::backdrop{background:#102528cf}@media(max-width:850px){.grid{display:flex;flex-direction:column}.image{position:static}.image img{max-height:50vh}.wrap{padding:12px}}
</style>
<header><h1>ELEC-VQA · 未决评分审理</h1><p>585 条待审评分 · 原始 Qwen 分数保留 · 助手暂定归类，等待你的审理</p></header>
<main class="wrap"><div class="note">1 = 错误／无有效证据；2 = 有效但不完整（仅量表允许时）；3 = 完全正确／证据充分。答案与证据分开打分。当前没有任何预填的人工评分。浏览器缓存不代替文件保存，请定期导出。</div>
<div class="bar" style="margin-top:18px"><select id="model"><option value="">全部模型</option><option>A</option><option>E</option><option>base</option><option>internvl</option><option>llava</option></select><select id="dimension"><option value="">答案＋证据</option><option value="answer">答案</option><option value="evidence">证据</option></select><select id="grade"><option value="">全部暂定分数</option><option value="3">暂定 3（优先）</option><option value="2">暂定 2</option><option value="1">暂定 1</option></select><select id="done"><option value="">全部状态</option><option value="pending">尚未审理</option><option value="reviewed">已经审理</option></select><input id="search" placeholder="搜索样本 ID、任务或问题"><button id="export" class="primary">导出审核 JSON</button><button id="import">导入审核 JSON</button><input type="file" id="file" accept=".json" hidden></div>
<div class="bar pager"><span id="status"></span><span><button id="prev">← 上一条</button> <span id="position"></span> <button id="next">下一条 →</button></span></div>
<div id="empty" hidden>当前筛选下没有条目。</div><div class="grid" id="content"><section class="box image"><div id="tags"></div><img id="image" alt="待审问题对应的原始数据集截图"><div class="bar"><a id="original" target="_blank" rel="noopener">打开原图</a><span class="muted">点击图片放大</span></div><div id="identity" class="muted"></div></section>
<section><article class="box"><h3>问题</h3><h2 id="question"></h2><h3>参考答案</h3><div id="reference_answer" class="text"></div><h3>参考证据</h3><div id="reference_evidence" class="text"></div><h3>模型完整输出</h3><div id="response" class="text response"></div></article>
<article class="box"><span class="score" id="provisional"></span><h3>暂定归类理由</h3><div id="reason" class="text"></div><div id="method" class="muted"></div><details><summary>原始 Qwen 未决理由和尝试分数</summary><pre id="raw" class="text response"></pre></details></article>
<article class="box review"><h2>你的审理</h2><div class="bar"><select id="human"><option value="">尚未审理</option><option value="1">1 — 错误 / 无有效证据</option><option value="2">2 — 有效但不完整</option><option value="3">3 — 完全正确 / 证据充分</option></select><button id="accept">接受本条暂定分数</button></div><textarea id="note" placeholder="审核意见（可选）"></textarea><div class="muted">选择与备注会自动保存在当前浏览器；只有点击接受或主动选择后才算人工审理。</div></article></section></div>
<footer class="muted">只处理测试集原先为 null 的记录；此页面不修改原始预测、参考标注或 Qwen 文件。<a href="README.md">范围与回填说明</a></footer></main>
<dialog id="zoom"><button id="close">关闭</button><br><img id="zoomImage" alt="完整图纸截图"></dialog>
<script type="application/json" id="payload">__DATA__</script><script>
const payload=JSON.parse(document.getElementById('payload').textContent), rows=payload.reviews;
const $=id=>document.getElementById(id),storageKey='elec-vqa-unresolved-human-v1';let decisions={};try{decisions=JSON.parse(localStorage.getItem(storageKey)||'{}')}catch(e){};let filtered=[],pos=0;
const current=()=>filtered[pos];const rating=r=>decisions[r.key]?.human_rating||r.human_rating;
function save(){let r=current();if(!r)return;let n=Number($('human').value)||null;if(n){decisions[r.key]={key:r.key,prediction_sha256:r.prediction_sha256,human_rating:n,human_note:$('note').value}}else delete decisions[r.key];try{localStorage.setItem(storageKey,JSON.stringify(decisions))}catch(e){alert('浏览器存储失败，请立即导出审核文件。')}status()}
function status(){$('status').textContent=`已审理 ${rows.filter(r=>rating(r)).length} / ${rows.length} · 当前筛选 ${filtered.length} 条`;}
function filter(){filtered=rows.filter(r=>(!$('model').value||r.model===$('model').value)&&(!$('dimension').value||r.dimension===$('dimension').value)&&(!$('grade').value||r.provisional_rating===Number($('grade').value))&&(!$('done').value||($('done').value==='reviewed'?!!rating(r):!rating(r)))&&(`${r.id} ${r.task} ${r.question}`.toLowerCase().includes($('search').value.toLowerCase()))).sort((a,b)=>b.provisional_rating-a.provisional_rating||a.key.localeCompare(b.key));pos=0;render()}
function render(){status();let r=current();$('empty').hidden=!!r;$('content').hidden=!r;$('position').textContent=r?`${pos+1} / ${filtered.length}`:'0 / 0';$('prev').disabled=!r||pos===0;$('next').disabled=!r||pos===filtered.length-1;if(!r)return;
 $('tags').replaceChildren(...[r.model,r.track,r.dimension,r.task].map(t=>{let x=document.createElement('span');x.className='pill';x.textContent=t;return x}));
 for(let f of ['question','reference_answer','reference_evidence','response'])$(f).textContent=r[f];$('identity').textContent=r.id+' · '+r.image;
 $('image').src='../../dataset/'+r.image;$('original').href=$('image').src;$('provisional').textContent=`暂定 ${r.provisional_rating} 分`;$('reason').textContent=r.provisional_reason;$('method').textContent='归类来源：'+r.method;$('raw').textContent=JSON.stringify({original:r.original_grade,attempt_candidates:r.raw_candidates},null,2);
 $('human').value=rating(r)||'';$('note').value=decisions[r.key]?.human_note||r.human_note||'';
}
for(let f of ['model','dimension','grade','done','search'])$(f).addEventListener(f==='search'?'input':'change',filter);
$('prev').onclick=()=>{pos=Math.max(0,pos-1);render()};$('next').onclick=()=>{pos=Math.min(filtered.length-1,pos+1);render()};$('human').onchange=save;$('note').oninput=save;$('accept').onclick=()=>{if(current()){$('human').value=current().provisional_rating;save()}};
$('export').onclick=()=>{let out={schema:'elec-vqa-human-review',exported_at:new Date().toISOString(),reviews:rows.map(r=>({key:r.key,id:r.id,track:r.track,dimension:r.dimension,model:r.model,prediction_sha256:r.prediction_sha256,provisional_rating:r.provisional_rating,human_rating:rating(r)||null,human_note:decisions[r.key]?.human_note||r.human_note||''}))};let u=URL.createObjectURL(new Blob([JSON.stringify(out,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download='ELEC-VQA_human_review.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};
$('import').onclick=()=>$('file').click();$('file').onchange=async()=>{try{let x=JSON.parse(await $('file').files[0].text()),known=new Map(rows.map(r=>[r.key,r])),next={...decisions};for(let d of (Array.isArray(x)?x:x.reviews)){if(![1,2,3].includes(d.human_rating))continue;let r=known.get(d.key);if(!r)throw Error('未知评分记录：'+d.key);if(d.prediction_sha256!==r.prediction_sha256)throw Error('响应哈希不一致：'+d.key);next[d.key]=d}decisions=next;localStorage.setItem(storageKey,JSON.stringify(decisions));filter();alert('已导入人工评分。')}catch(e){alert('未能导入：'+e.message)}};
$('image').onclick=()=>{$('zoomImage').src=$('image').src;$('zoom').showModal()};$('close').onclick=()=>$('zoom').close();filter();
</script></html>'''
(O/'index.html').write_text(page.replace('__DATA__',data),encoding='utf-8')
summary=list(csv.DictReader((O/'tables/overall.csv').open(encoding='utf-8-sig')))
lines=['\\begin{table}[t]','\\centering','\\caption{Provisional assistant-resolved test scores, pending human adjudication. Original non-null Qwen ratings are retained.}','\\begin{tabular}{llrr}','\\toprule','Protocol & Model & Answer (\\%) & Evidence (\\%) \\\\','\\midrule']
for tr in ['direct','explain']:
 for r in summary:
  if r['track']!=tr or r['dimension']!='answer':continue
  ev=next((e for e in summary if e['track']==tr and e['model']==r['model'] and e['dimension']=='evidence'),None)
  lines.append(f'{tr} & {r["model"]} & {float(r["full_credit_rate"])*100:.2f} & '+(f'{float(ev["full_credit_rate"])*100:.2f}' if ev else '--')+r' \\')
lines+=['\\bottomrule','\\end{tabular}','\\end{table}']
(O/'tables/overall.tex').write_text('\n'.join(lines)+'\n',encoding='utf-8')
print('Review page generated:',O/'index.html')
